// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    // Fuzzed parameters: an address to act as the callee and a bytes32 to help construct a recipient
    // We use the callee address to point to a Recording helper so we can observe calls made by c.
    function testFuzz_property(address calleeAddr, bytes32 rand) public {
        // Keep calleeAddr non-zero and not the c contract itself
        vm.assume(calleeAddr != address(0));
        vm.assume(calleeAddr != address(c));

        // Deploy a recorder helper that implements the exact transferFrom signature
        Recorder recorder = new Recorder();

        // Build a non-empty _tos array to separate behavior (mutant requires empty)
        address[] memory tos = new address[](1);
        // Derive a recipient from fuzz bytes to keep inputs fuzzy
        tos[0] = address(uint160(uint256(keccak256(abi.encodePacked(rand, calleeAddr)))));

        // Now call c.transfer with the recorder's address as the caddress.
        // The reference implementation always returns true and does not revert for any _tos length > 0
        bool ok;
        try c.transfer(address(this), address(recorder), tos, 123) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: reference never reverts for any admissible input -> ok must be true.
        // The mutant (which requires _tos.length == 0) will make ok == false for non-empty tos.
        assertTrue(ok);

        // Additionally, ensure the recorder observed the delegated call (sanity for the reference)
        // The recorder increments callCount for each transferFrom; since we passed one recipient, expect 1
        assertTrue(recorder.callCount() == 1);
    }
}

// A small recorder that matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
// It records calls so the test can observe how many times C invoked the external call and with what args.
contract Recorder {
    uint256 public callCount;
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;

    // Exact function signature expected by C's encoded call
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        callCount += 1;
        lastFrom = from;
        lastTo = to;
        lastValue = v;
        return true;
    }

    // Fallback to catch malformed calls if any (not expected) and still record
    fallback() external payable {
        callCount += 1;
    }
}
